-- Writing interface 1; predecessor 007. Engine owns transaction/checksum.
CREATE TABLE IF NOT EXISTS "writing_delivery"(branch TEXT NOT NULL,id TEXT NOT NULL,"audience" TEXT NOT NULL,"form" TEXT NOT NULL CHECK("form" IN ('narration','dialogue','situation','scenario','event','history','discovery','reflection','recap','description')),"text" TEXT NOT NULL,"scene" TEXT,"supersedes" TEXT,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"audience") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"scene") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"supersedes") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "dialogue_reception"(branch TEXT NOT NULL,id TEXT NOT NULL,"listener" TEXT NOT NULL,"turn" TEXT NOT NULL,"interpretation" TEXT NOT NULL,"certainty" TEXT NOT NULL CHECK("certainty" IN ('tentative','confident','unknown')),"response" TEXT,"supersedes" TEXT,PRIMARY KEY(branch,id),FOREIGN KEY(branch,id) REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"listener") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"turn") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(branch,"supersedes") REFERENCES records(branch,id) DEFERRABLE INITIALLY DEFERRED);
INSERT INTO engine_versions(component,version) VALUES('writing_interface','1');
